export function greet(name) {
  return "Hi";
}

export function total(items) {
  let sum = 0;
  for (const item of items) sum += item.price;
  return sum;
}

rawInput.command:
mkdir -p docs && cp mock.png docs/mock-copy.png && python3 -c "
import pathlib
src = pathlib.Path('mock.png').read_bytes()
dst = pathlib.Path('docs/mock-copy.png').read_bytes()
print('src', len(src), 'dst', len(dst), 'match', src == dst)
" && node --input-type=module -e "
import { greet } from './app.js';
const out = greet('Ada');
if (out !== 'Hello, Ada!') { console.error('unexpected', out); process.exit(1); }
console.log(out);
" && git status --short && git rev-parse --is-inside-work-tree 2>/dev/null || true

